using System;using System.IO;using System.Linq;using System.Runtime.InteropServices;using System.Collections.Generic;using System.Web.Script.Serialization;using interop.ICApiIronCAD;
namespace RockPro{public static class LatchInProcess{static IZDoc D(object x){return x is IZDoc?(IZDoc)x:(IZDoc)Marshal.GetObjectForIUnknown(new IntPtr(Convert.ToInt64(x)));}public static int Run(string folder){var j=new JavaScriptSerializer{MaxJsonLength=64000000};var result=new Dictionary<string,object>();try{var q=(Dictionary<string,object>)j.DeserializeObject(File.ReadAllText(Path.Combine(folder,"request.json")));if((string)q["contract"]!="rockpro-tv-wall-edit-v1"||System.Diagnostics.Process.GetCurrentProcess().Id!=Convert.ToInt32(q["expected_pid"]))throw new Exception("Wrong host/request");dynamic legacy=Marshal.GetActiveObject("IronCAD.Application");var app=(IZBaseApp)legacy.ZIronCADApp;if(!app.ApiVersion.StartsWith("29."))throw new Exception("2027 required");var doc=((Array)app.GetAllOpenDocs()).Cast<object>().Select(D).Single(d=>d.Name==(string)q["model"]);var s=(IZSceneDoc)doc;var manifest=(Dictionary<string,object>)j.DeserializeObject((string)s.GetTopElement().get_CustomPropMgr(false).GetValueByName("RockPro.MountCounts.v1"));if((string)manifest["contract"]!="rockpro-tv-counts-v3")throw new Exception("Requires prepared wall mapping v3");var allowed=((object[])manifest["portable_rows"]).Cast<Dictionary<string,object>>().SelectMany(row=>new[]{"wall","section","count","center","spread","vertical"}.Where(row.ContainsKey).Select(key=>(string)row[key])).ToArray();var changes=(Dictionary<string,object>)q["changes"];foreach(var key in changes.Keys)if(!allowed.Contains(key))throw new Exception("Parameter outside portable-row allowlist: "+key);foreach(var pair in changes){string text=(string)pair.Value;double value;if(!Double.TryParse(text.Replace(" mm",""),System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out value)||Double.IsNaN(value)||Double.IsInfinity(value))throw new Exception("Non-finite/non-numeric mounting value");}var previous=changes.Keys.ToDictionary(n=>n,n=>s.ParameterMgr.GetParameterByName(n).Expression);try{foreach(var pair in changes)s.ParameterMgr.GetParameterByName(pair.Key).Expression=(string)pair.Value;s.Update();foreach(var pair in changes){var parameter=s.ParameterMgr.GetParameterByName(pair.Key);double requested=Double.Parse(((string)pair.Value).Replace(" mm",""),System.Globalization.CultureInfo.InvariantCulture);double actual=parameter.Value*(parameter.Type==eZParamType.Z_PARAMETER_TYPE_LENGTH?1000:1);if(Math.Abs(requested-actual)>1e-6)throw new Exception("IronCAD did not accept parameter "+pair.Key);}}catch{foreach(var pair in previous)s.ParameterMgr.GetParameterByName(pair.Key).Expression=pair.Value;s.Update();throw;}app.ActiveDoc=doc;result["changes"]=changes;result["manual_apply_calls"]=0;result["manual_start_calls"]=0;result["passed"]=true;}catch(Exception ex){result["passed"]=false;result["error"]=ex.ToString();}File.WriteAllText(Path.Combine(folder,"result.json"),j.Serialize(result));return (bool)result["passed"]?0:1;}}}